@pytest.fixture(scope="module")
def compiler():
    value = os.environ.get("DEWY_CORE_COMPILER")
    if not value:
        pytest.skip("run through python3 -m tools.core test")
    return Path(value).resolve(strict=True)


def _case_parameter(case):
    if case["classification"] == "accurate":
        return pytest.param(case, id=case["name"])
    proposal = f"{case['want_line']}:{case['want_col']}: {case['want_message']}"
    return pytest.param(case, id=case["name"],
                        marks=pytest.mark.xfail(strict=True, reason=f"proposed: {proposal}"))


@pytest.mark.core_quick
@pytest.mark.parametrize("case", [_case_parameter(case) for case in CASES])
def test_parse_diagnostic_accuracy(compiler, tmp_path, case):
    source = (ROOT / case["fixture"]).read_text() if case["fixture"] else case["source"]
    path = tmp_path / "input.dewy"
    path.write_text(source + ("" if source.endswith("\n") else "\n"))
    result = subprocess.run([str(compiler), "check", str(path)], capture_output=True,
                            text=True, timeout=60, check=False)
    assert result.returncode != 0, f"accepted malformed input: {case['name']}"
    match = re.search(r"(?m)^.*?:(\d+):(\d+): error: (.*)$", result.stderr)
    assert match, result.stderr
    got = (int(match[1]), int(match[2]), match[3])
    expected = (case["want_line"], case["want_col"], case["want_message"])
    assert got == expected
